import { byId, totalAge, dedupeSorted } from './module.mjs';
// Reference with lodash semantics: keyBy (last wins, key = String(id)), sumBy(prop) (0 when empty), sortedUniq.
const refById = (rows) => { const o = {}; for (const r of rows) o[r.id] = r; return o; };
const refTotal = (rows) => rows.reduce((s, r) => s + r.age, 0);
const refDedupe = (v) => v.filter((x, i) => i === 0 || x !== v[i - 1]);
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
let fails = 0, n = 0;
const check = (name, got, want) => { n++; if (!eq(got, want)) { fails++; console.log('FAIL', name, JSON.stringify(got), JSON.stringify(want)); } };
const names = ['choi','jung','kim','lee','park'];
const rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const rowsRnd = (max) => Array.from({ length: rnd(0, max) }, () => ({ id: rnd(0, 9), name: names[rnd(0,4)], age: rnd(18, 60) }));
// Examples from the task
const ex1 = [{"id":4,"name":"lee","age":34},{"id":4,"name":"jung","age":55},{"id":3,"name":"park","age":51},{"id":1,"name":"lee","age":44},{"id":3,"name":"kim","age":57}];
const ex2 = [{"id":5,"name":"jung","age":20},{"id":4,"name":"lee","age":41}];
const ex3 = [{"id":0,"name":"choi","age":52},{"id":8,"name":"choi","age":43},{"id":1,"name":"lee","age":34},{"id":3,"name":"choi","age":36},{"id":3,"name":"jung","age":43},{"id":7,"name":"lee","age":55}];
for (const r of [ex1, ex2, ex3, []]) { check('byId', byId(r), refById(r)); check('totalAge', totalAge(r), refTotal(r)); }
check('byId-empty', byId([]), {});
for (const v of [[1,4,7,15], [-4,5,9], [], [3], [2,2,2], [-5,-5,20,20]]) check('dedupe', dedupeSorted(v), refDedupe(v));
for (let i = 0; i < 20000; i++) {
  const r = rowsRnd(12); check('byId', byId(r), refById(r)); check('totalAge', totalAge(r), refTotal(r));
  const v = Array.from({ length: rnd(0, 20) }, () => rnd(-5, 20)).sort((a, b) => a - b);
  check('dedupe', dedupeSorted(v), refDedupe(v));
}
console.log(`checks: ${n}, failures: ${fails}`);
EOF
node "$S/check.mjs"; echo "exit $?"

